using System.Diagnostics;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class MissionEightTests {
 static string outputFolder=".";
 static readonly List<string> checks=new();static readonly List<object> runs=new();
 static void Check(bool ok,string label){if(!ok)throw new InvalidDataException("FAIL M8: "+label);checks.Add(label);Console.WriteLine("PASS M8: "+label);}
 static Simulation Load(string root,int branch=2){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE08.ETA"));new VisualCatalog().Apply(w);return new(w,new(){StartingLevels=Simulation.UnlockData.Missions.First(m=>m.Mission==8).Levels.ToArray(),SelectedBranch=branch});}
 static void Until(Simulation s,Func<bool> predicate,int limit,string label){for(int i=0;i<limit&&!predicate()&&!s.MissionWon&&!s.MissionLost;i++)s.Step();if(!predicate()){File.WriteAllText(Path.Combine(outputFolder,"failed-route.snapshot.json"),s.Serialize());Console.WriteLine(JsonSerializer.Serialize(s.Constructions));}
Check(predicate(),label+" tick="+s.Tick+" lost="+s.MissionLost);}
 static Simulation Roundtrip(Simulation s,string root){var next=Load(root);next.Restore(s.Serialize());return next;}
 static int Coast(Simulation s,Actor a,bool north)=>Enumerable.Range(north?12:84,35).SelectMany(y=>Enumerable.Range(108,16).Select(x=>y*256+x)).Where(c=>s.Passable(c&255,c>>8)&&s.ConstructionGrass(c)).OrderBy(c=>Math.Abs((c>>8)-(north?40:100))).ThenBy(c=>c&255).First();
 static void InitializePort(Simulation s){var col=s.World.Units.First(a=>a.Owner==0&&a.Type==9&&VisualCatalog.Visible(a));var port=s.World.Buildings.Where(b=>b.Type==18).OrderBy(b=>Math.Abs((b.Cell&255)-col.X/1024)+Math.Abs((b.Cell>>8)-col.Y/1024)).First();Check(s.CanClaimHeliport(col,port.Slot)&&s.EnterBuilding(col,port.Slot),"colonist enters native abandoned heliport");}
 public static void Run(string root,string output){
  outputFolder=Path.GetDirectoryName(Path.GetFullPath(output))!;checks.Clear();runs.Clear();var s=Load(root);Check(s.HasMissionEnding&&!s.MissionWon&&!s.MissionLost,"mission eight starts unfinished");Check(s.World.Width==128&&s.World.Height==128&&s.World.Units.Count==14&&s.World.Buildings.Count==6,"native opening map actors and buildings retained");Check(s.World.Resources[0]==50&&s.World.Resources[4]==30&&s.World.Resources[8]==0,"native player stock 50/30/0");Check(s.World.Buildings.Count(b=>b.Type==18&&b.Owner==200)==4,"four abandoned heliports require actual occupation");Check(!s.World.Units.Any(a=>a.Type==17),"no balloon before heliport activation");var opening=s.Serialize();s.Restore(opening);Check(s.Serialize()==opening,"opening exact save roundtrip");
  var objectives=new ObjectiveReader();objectives.Open("MONDE08.ETA",false);objectives.Move(1);Check(objectives.Lines.Any(l=>l.Contains("oceano",StringComparison.OrdinalIgnoreCase)),"Portuguese ocean objective");
  for(int branch=0;branch<4;branch++)foreach(bool north in new[]{true,false}){
   s=Load(root,branch);InitializePort(s);var during=s.Serialize();s.Restore(during);Check(s.Serialize()==during,"save during unclaimed heliport entry");Until(s,()=>s.Ocean.Balloons.Any(a=>a.Owner==0),1500,"first occupied heliport supplies balloon");var balloon=s.World.Units.First(a=>a.Type==17&&a.Owner==0);Check(s.Ocean.Balloons.Count(a=>a.Owner==0)==1&&balloon.Health==1,"single indestructible balloon per clan");
   var builder=s.World.Units.First(a=>a.Owner==0&&a.Type==7);int dest=Coast(s,builder,north);Check(s.Order(builder,dest&255,dest>>8)&&s.WaitingForFlight(builder),"ordinary distant movement requests ocean crossing");
   var col=s.World.Units.First(a=>a.Owner==0&&a.Type==9&&VisualCatalog.Visible(a));Check(s.Order(col,(dest&255)+1,dest>>8)&&s.WaitingForFlight(col),"second passenger joins crossing");Until(s,()=>s.Ocean.Jobs.Any(j=>j.Actor==builder.Slot&&j.Stage==2),1500,"builder boards balloon");Check(!VisualCatalog.Visible(builder),"onboard passenger not drawn as a ground troop");
   s=Roundtrip(s,root);builder=s.World.Units.First(a=>a.Owner==0&&a.Type==7);Check(s.Ocean.Jobs.Count>0,"passengers survive boarding save");Until(s,()=>!s.WaitingForFlight(builder),4500,"flight crosses ocean and disembarks builder");Check(builder.X/1024>=106&&VisualCatalog.Visible(builder)&&s.InSight(builder.Y/1024*256+builder.X/1024),"eastern land naturally revealed by flight");
   int siteCell=Enumerable.Range(north?10:82,40).SelectMany(y=>Enumerable.Range(106,19).Select(x=>y*256+x)).Where(c=>s.PlacementError(builder,2,c)==null&&s.InSight(c)).OrderBy(c=>Math.Abs((c&255)-builder.X/1024)+Math.Abs((c>>8)-builder.Y/1024)).FirstOrDefault(-1);
   Check(siteCell>=0&&s.StartConstruction(builder,2,siteCell),"sanctuary begins with actual stock on discovered coast");Check(!s.MissionWon,"unfinished sanctuary does not win");var clock=Stopwatch.StartNew();Until(s,()=>s.MissionWon,10000,"normal crossing and construction conclude mission");runs.Add(new{Branch=branch,Coast=north?"north":"south",Tick=s.Tick,Food=s.World.Resources[0],Stone=s.World.Resources[4],BalloonJobs=s.Ocean.Jobs.Count,RealSeconds=clock.Elapsed.TotalSeconds});
   var won=s.Serialize();s.Restore(won);Check(s.MissionWon&&s.Serialize()==won,"victory save persists");if(branch==2&&north)File.WriteAllText(Path.Combine(Path.GetDirectoryName(output)!,"natural-victory.snapshot.json"),won);
   s.RequestNextMission();Check(s.ChooseNextResearch(branch),"choose technology after victory");var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/"+s.EighthNextMap));new VisualCatalog().Apply(w);var next=new Simulation(w,s.ProgressForNextMission());Check(next.MissionNumber==9&&next.Campaign.CompletedMission==8,"8 to 9 campaign boundary");
  }
  s=Load(root);InitializePort(s);Until(s,()=>s.Ocean.Balloons.Any(a=>a.Owner==0),1500,"port ready for edge cases");var a=s.World.Units.First(a=>a.Owner==0&&a.Type==7);int goal=Coast(s,a,true);Check(s.Order(a,goal&255,goal>>8),"queue cancellable flight");s.Stop(a);Check(!s.WaitingForFlight(a)&&VisualCatalog.Visible(a),"stop cancels waiting flight without losing actor");
  var stable=s.Serialize();var forged=JsonNode.Parse(stable)!;forged["Ocean"]!["Balloons"]![0]!["Owner"]=(forged["Ocean"]!["Balloons"]![0]!["Owner"]!.GetValue<int>()+1)%4;bool rejected=false;try{s.Restore(forged.ToJsonString());}catch(InvalidDataException){rejected=true;}Check(rejected&&s.Serialize()==stable,"forged balloon ownership rejected atomically");
  s.Restart();Check(s.Ocean.Balloons.Count==0&&s.World.Buildings.Count(b=>b.Owner==200)==4,"restart returns abandoned heliports and no balloons");
  s=Load(root);Until(s,()=>s.World.Buildings.Any(b=>b.Owner==3&&b.Type==2&&Simulation.EighthCoast(b.Cell)),20000,"opponent completes real coastal sanctuary");Check(!s.MissionWon&&!s.MissionLost,"opponent arrival does not end player mission");var waiting=s.Serialize();s.Restore(waiting);Check(!s.MissionWon&&!s.MissionLost&&s.EighthNextMap!="MONDE09A.ETA","enemy expansion and next-map variant persist");
  var fixture=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE08.ETA"));new VisualCatalog().Apply(fixture);var template=fixture.Units.First(a=>a.Owner==0&&a.Type==9&&a.LegacyState==7);for(int i=0;i<5;i++){var copy=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(template))!;copy.Slot=100+i;copy.X=14*1024;copy.Y=54*1024;fixture.Units.Add(copy);}s=new(fixture);InitializePort(s);Until(s,()=>s.Ocean.Balloons.Any(a=>a.Owner==0),1500,"isolated crowd fixture activates port");var passengers=s.World.Units.Where(a=>a.Owner==0&&a.Type==9&&VisualCatalog.Visible(a)).ToList();a=s.World.Units.First(a=>a.Owner==0&&a.Type==7);a.Rock=3;passengers.Insert(0,a);goal=Coast(s,a,true);foreach(var passenger in passengers)Check(s.Order(passenger,goal&255,goal>>8),"group passenger queues transport");bool sawFive=false,sawQueue=false;int max=0;for(int i=0;i<14000&&s.Ocean.Jobs.Count>0;i++){s.Step();int active=s.Ocean.Jobs.Count(j=>j.Stage>0&&s.World.Units.Any(b=>b.Slot==j.Balloon&&b.Owner==0));max=Math.Max(max,active);sawFive|=active==5;sawQueue|=s.Ocean.Jobs.Any(j=>j.Stage==0&&s.World.Units.Any(b=>b.Slot==j.Balloon&&b.Owner==0));}Check(sawFive&&sawQueue&&max==5&&passengers.All(a=>!s.WaitingForFlight(a)&&a.X/1024>=106),"five passenger cap and excess queue cross in successive flights");Check(a.Rock==3&&s.World.Resources[0]==50&&s.World.Resources[4]==30,"cargo preserved and flight charges no resources");
  var multiPort=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE08.ETA"));new VisualCatalog().Apply(multiPort);multiPort.Units.RemoveAll(a=>a.Owner!=0);s=new(multiPort);InitializePort(s);Until(s,()=>s.Ocean.Balloons.Any(a=>a.Owner==0),1500,"isolated multi-port fixture activates original port");var secondClaim=JsonNode.Parse(s.Serialize())!;secondClaim["Ocean"]!["Claims"]!["0"]=0;s.Restore(secondClaim.ToJsonString());var multiSave=s.Serialize();s.Restore(multiSave);Check(s.Serialize()==multiSave&&s.Ocean.Claims.Count==2&&s.Ocean.Balloons.Count==1,"claiming an earlier-slot second port preserves original balloon seed and exact save");
  File.WriteAllText(output,JsonSerializer.Serialize(new{Passed=true,Checks=checks.Count,Assertions=checks,Runs=runs,Limits="Eight headless routes with ordinary orders and native stock; no manual UI campaign. Forged-state edge test is isolated."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS M8 total "+checks.Count);
 }
}
